PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS metadata(version INTEGER NOT NULL);
INSERT INTO metadata SELECT 2 WHERE NOT EXISTS(SELECT 1 FROM metadata);
CREATE TABLE IF NOT EXISTS users(id TEXT PRIMARY KEY,username TEXT UNIQUE NOT NULL,password_hash TEXT NOT NULL,role TEXT NOT NULL CHECK(role IN ('participant','staff','organizer','restaurant','admin')),tenant TEXT NOT NULL,active INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS events(id TEXT PRIMARY KEY,tenant TEXT NOT NULL,title TEXT NOT NULL,capacity INTEGER NOT NULL CHECK(capacity>=0),meal_capacity INTEGER NOT NULL CHECK(meal_capacity>=0),price INTEGER NOT NULL CHECK(price>=0),currency TEXT DEFAULT 'EUR',timezone TEXT DEFAULT 'Europe/Rome');
CREATE TABLE IF NOT EXISTS registrations(id TEXT PRIMARY KEY,event_id TEXT NOT NULL REFERENCES events(id),owner TEXT NOT NULL,name TEXT NOT NULL,meal INTEGER NOT NULL CHECK(meal IN (0,1)),state TEXT NOT NULL CHECK(state IN ('requested','rejected','held','paid','failed','expired')),expires REAL NOT NULL,amount INTEGER NOT NULL CHECK(amount>=0),token TEXT UNIQUE NOT NULL,idem TEXT NOT NULL,UNIQUE(event_id,owner,idem));
CREATE TABLE IF NOT EXISTS payments(id TEXT PRIMARY KEY,registration_id TEXT NOT NULL REFERENCES registrations(id),state TEXT NOT NULL,amount INTEGER NOT NULL,UNIQUE(registration_id));
CREATE TABLE IF NOT EXISTS scans(id TEXT PRIMARY KEY,registration_id TEXT NOT NULL REFERENCES registrations(id),service TEXT CHECK(service IN ('event','meal')),actor TEXT NOT NULL,created REAL NOT NULL,UNIQUE(registration_id,service));
CREATE TABLE IF NOT EXISTS incidents(id TEXT PRIMARY KEY,event_id TEXT NOT NULL REFERENCES events(id),actor TEXT NOT NULL,message TEXT,lat REAL,lon REAL,accuracy REAL,state TEXT CHECK(state IN ('received','acknowledged','closed')),assignee TEXT,created REAL,idem TEXT NOT NULL,closed_by TEXT,closed_at REAL,close_reason TEXT,UNIQUE(event_id,actor,idem));
CREATE TABLE IF NOT EXISTS notifications(id TEXT PRIMARY KEY,incident_id TEXT NOT NULL REFERENCES incidents(id),channel TEXT DEFAULT 'staff_demo_inbox',state TEXT DEFAULT 'available_in_inbox');
CREATE TABLE IF NOT EXISTS audit(seq INTEGER PRIMARY KEY AUTOINCREMENT,actor TEXT NOT NULL,action TEXT NOT NULL,entity TEXT,created REAL);
CREATE TRIGGER IF NOT EXISTS audit_no_update BEFORE UPDATE ON audit BEGIN SELECT RAISE(ABORT,'append only'); END;
CREATE TRIGGER IF NOT EXISTS audit_no_delete BEFORE DELETE ON audit BEGIN SELECT RAISE(ABORT,'append only'); END;
